import{_ as s,o as e,c as i,a2 as o}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"1.6满仓震荡方案","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}]]},"headers":[],"relativePath":"zh/full-storage-oscillation-plan.md","filePath":"zh/page-JEibHxjUhjwaznRy5jp6oc.md"}'),r={name:"zh/full-storage-oscillation-plan.md"};function l(p,a,n,t,c,d){return e(),i("div",null,[...a[0]||(a[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-6满仓震荡方案" aria-hidden="true"></span><h1 id="_1-6满仓震荡方案" tabindex="-1">1.6满仓震荡方案 <a class="header-anchor" href="#_1-6满仓震荡方案" aria-label="Permalink to &quot;1\\.6满仓震荡方案&quot;">​</a></h1><blockquote><p>源页面 ID：<code>JEibHxjUhjwaznRy5jp6oc</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red"><strong>#言：我息壤呢？</strong></span></p><p>待做：</p><p>高效销毁的合理适配，净水节点？药液处理？水泵数量？(暂时不加入)</p><p>需求：</p><p>景玉谷12双口息壤，自启动12双口9准入口方案已做好，赤石点：设备数爆炸</p><p>其他部分：</p><p>应龙关去掉息壤加压，自连暗管外置，加东西（分离芯）</p><p>主基地待压缩（精炼炉，污水处理垃圾桶，壤晶线，炼铁磨粉分离芯，半速电池/，息壤震荡/，息壤液气转化/，息壤总线/，重息壤/）【最主要问题：电池线没出，高效销毁没出，外置水泵汇流器，超50格暗管，息壤震荡自启动】</p><p>当前布局：</p><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><span class="logistics-source-anchor" id="景玉谷" aria-hidden="true"></span><h2 id="景玉谷" tabindex="-1">景玉谷 <a class="header-anchor" href="#景玉谷" aria-label="Permalink to &quot;景玉谷&quot;">​</a></h2><p>12烘炉9双口+原首墩+适量分离芯/磨粉</p><p><span class="mark-grey">言：12息壤/3赤铜精练+3粉碎/1-2分离芯/种植组（1个芽针1个锦草）+2粉碎是比较确定的？剩下空位可以塞中电或者蓝铁精炼+粉碎</span></p><p>首墩：全空</p><p>主基地：加中电</p><p>应龙关：不变</p><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><span class="logistics-source-anchor" id="散装模块" aria-hidden="true"></span><h2 id="散装模块" tabindex="-1">散装模块 <a class="header-anchor" href="#散装模块" aria-label="Permalink to &quot;散装模块&quot;">​</a></h2><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><span class="logistics-source-anchor" id="蓝铁处理" aria-hidden="true"></span><h3 id="蓝铁处理" tabindex="-1">蓝铁处理 <a class="header-anchor" href="#蓝铁处理" aria-label="Permalink to &quot;蓝铁处理&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="16满仓震荡方案"></p><div class="logistics-image-caption" data-source-block="K6uojhba5PhZY4h7JS1DHr"><p>赫塔-蓝铁精炼及打粉</p></div><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><span class="logistics-source-anchor" id="息壤" aria-hidden="true"></span><h3 id="息壤" tabindex="-1">息壤 <a class="header-anchor" href="#息壤" aria-label="Permalink to &quot;息壤&quot;">​</a></h3><p><span class="mark-red">东西呢快点端上来！！！</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><span class="logistics-source-anchor" id="息壤液满仓震荡模块" aria-hidden="true"></span><h3 id="息壤液满仓震荡模块" tabindex="-1">息壤液满仓震荡模块 <a class="header-anchor" href="#息壤液满仓震荡模块" aria-label="Permalink to &quot;息壤液满仓震荡模块&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><span class="logistics-source-anchor" id="控息壤" aria-hidden="true"></span><h4 id="控息壤" tabindex="-1">控息壤 <a class="header-anchor" href="#控息壤" aria-label="Permalink to &quot;控息壤&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><span class="logistics-source-anchor" id="控水" aria-hidden="true"></span><h4 id="控水" tabindex="-1">控水 <a class="header-anchor" href="#控水" aria-label="Permalink to &quot;控水&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="16满仓震荡方案"></p><p>填充物：除了最左断电箱都填充250锦草、断电池填充4杂物和传送带长的锦草种子</p><p>应该是省了非常多设备数了，代价仅是4管道件。不过我还没压缩（（</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-66cb72c1992c90de.q90-436844d24ec0f6d8.webp" alt="16满仓震荡方案"></p><div class="logistics-image-caption" data-source-block="kV6LSLxSlxeHjErvDqotD1"><p>优先级均为分流器优先，应该拍下去就是对的</p></div><p>初步压缩完成；断电池制备较久，不知道要不要优化</p><p>《明日方舟：终末地》蓝图 [武陵断电池]分享码EF01E75U77u25o5683uIa 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [震荡息壤液]分享码EF01081388U91i1o5E179 请复制后前往游戏中使用。</p></div>',1)])])}const b=s(r,[["render",l]]);export{u as __pageData,b as default};
